// Generated by scripts/page-evals/build-skill.ts from demo/note-pages/*-app/. Don't edit.
export const APP_EXAMPLES: Record<string, { files: Record<string, string> }> = {
  "training": {
    "files": {
      "/README.md": "# Training\n\nA strength-training app. Its data is JSON in the app's own store (see `src/data.js`):\n`plan` (the days and their exercises) and the `log` collection (every set). The first time it\nopens, it starts from the tables the note held before it became an app.\n\n- `src/App.jsx`: the screens (Today, Plan, Progress) in an amber-ui Shell, plus Settings.\n- `src/screens/`: one file per screen. `src/components/`: pieces used by several screens.\n- Settings (units, weekly goal) are kept with useSettings. The note-list line comes from setSummary.\n",
      "/index.html": "<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <title>Training</title>\n  <link rel=\"stylesheet\" href=\"/src/styles.css\">\n</head>\n<body>\n  <div id=\"app\"></div>\n  <script type=\"module\" src=\"/src/main.jsx\"></script>\n</body>\n</html>\n",
      "/src/App.jsx": "import { Router, Route } from \"amber-router\";\nimport { Shell, Icon } from \"amber-ui\";\nimport Today from \"./screens/Today.jsx\";\nimport Plan from \"./screens/Plan.jsx\";\nimport PlanDay from \"./screens/PlanDay.jsx\";\nimport Progress from \"./screens/Progress.jsx\";\nimport Settings from \"./screens/Settings.jsx\";\n\nconst screens = [\n  { path: \"/\", label: \"Today\", icon: <Icon name=\"clock\" /> },\n  { path: \"/plan\", label: \"Plan\", icon: <Icon name=\"calendar\" /> },\n  { path: \"/progress\", label: \"Progress\", icon: <Icon name=\"chart\" /> },\n];\n\nexport default function App() {\n  return (\n    <Shell items={screens} title=\"Training\">\n      <Router>\n        <Route path=\"/\" component={Today} default />\n        <Route path=\"/plan\" component={Plan} />\n        <Route path=\"/plan/:day\" component={PlanDay} />\n        <Route path=\"/progress\" component={Progress} />\n        <Route path=\"/settings\" component={Settings} />\n      </Router>\n    </Shell>\n  );\n}\n",
      "/src/components/ScreenHeader.jsx": "import { back, route } from \"amber-router\";\nimport { Button, Icon } from \"amber-ui\";\n\n// The title of a screen, with Back for pushed screens and Settings for the others.\nexport default function ScreenHeader({ title, subtitle, canGoBack }) {\n  return (\n    <header class=\"screen-header\">\n      {canGoBack && <Button variant=\"secondary\" size=\"small\" class=\"round\" aria-label=\"Back\" onClick={back}><Icon name=\"back\" /></Button>}\n      <div class=\"screen-header__text\">\n        <h1>{title}</h1>\n        {subtitle && <p>{subtitle}</p>}\n      </div>\n      {!canGoBack && <Button variant=\"secondary\" size=\"small\" class=\"round\" aria-label=\"Settings\" onClick={() => route(\"/settings\")}><Icon name=\"gear\" /></Button>}\n    </header>\n  );\n}\n",
      "/src/components/WeightChart.jsx": "// Weight over time for one exercise, drawn to scale in SVG.\nexport default function WeightChart({ points, label }) {\n  if (points.length < 2) return <p class=\"muted\">Log it twice to see a line.</p>;\n  const W = 600, H = 170, lo = Math.min(...points.map((p) => p.kg)) - 5, hi = Math.max(...points.map((p) => p.kg)) + 5;\n  const x = (i) => 30 + i * (W - 60) / (points.length - 1);\n  const y = (kg) => H - 26 - (kg - lo) / (hi - lo) * (H - 46);\n  return (\n    <svg class=\"chart\" viewBox={`0 0 ${W} ${H}`} role=\"img\" aria-label={label}>\n      <polyline fill=\"none\" stroke=\"var(--amber-accent)\" stroke-width=\"3\" points={points.map((p, i) => `${x(i)},${y(p.kg)}`).join(\" \")} />\n      {points.map((p, i) => (\n        <g>\n          <circle cx={x(i)} cy={y(p.kg)} r=\"4.5\" fill=\"var(--amber-accent)\" />\n          <text x={x(i)} y={H - 6} text-anchor=\"middle\">{p.date.slice(5).replace(\"-\", \"/\")}</text>\n        </g>\n      ))}\n    </svg>\n  );\n}\n",
      "/src/data.js": "// Training's data is JSON in the app's own store:\n//   plan: [{ day: \"Mon\", workout: \"Upper\", exercises: [\"Bench press\", ...] }]\n//   log (a collection): { id, date, exercise, sets, reps, weight }\n// The first time, it starts from the tables the note held before it became an app.\nimport { useStore, useCollection, useImported, batch } from \"amber\";\n\nexport const DAYS = [\"Sun\", \"Mon\", \"Tue\", \"Wed\", \"Thu\", \"Fri\", \"Sat\"];\nexport const DEFAULTS = { unit: \"kg\", goal: 3 };\nexport const today = () => new Date().toLocaleDateString(\"sv-SE\"); // YYYY-MM-DD, local\nexport const weight = (kg, unit) => unit === \"lb\" ? `${Math.round(kg * 2.2046)} lb` : `${kg} kg`;\nexport const lastSet = (log, name) => [...log.items].reverse().find((s) => s.exercise === name);\n\nlet importing = false;\n\nexport function useTraining() {\n  const [plan, setPlan] = useStore(\"plan\", null);\n  const log = useCollection(\"log\");\n  const imported = useImported();\n  if (plan === null && imported && !importing) {\n    importing = true;\n    const t = imported.tables || {};\n    batch(async () => {\n      setPlan((t.Plan || []).map((r) => ({ day: r.Day, workout: r.Workout, exercises: r.Exercises.split(\",\").map((s) => s.trim()) })));\n      for (const r of t.Log || []) log.add({ date: r.Date, exercise: r.Exercise, sets: +r.Sets, reps: +r.Reps, weight: +r.Weight });\n    });\n  }\n  return { plan: plan || [], log };\n}\n",
      "/src/main.jsx": "import { render } from \"preact\";\nimport App from \"./App.jsx\";\n\nrender(<App />, document.getElementById(\"app\"));\n",
      "/src/screens/Plan.jsx": "import { List, ListRow } from \"amber-ui\";\nimport ScreenHeader from \"../components/ScreenHeader.jsx\";\nimport { useTraining } from \"../data.js\";\n\nexport default function Plan() {\n  const { plan } = useTraining();\n  return (\n    <div class=\"screen\">\n      <ScreenHeader title=\"Plan\" subtitle={`${plan.length} sessions a week`} />\n      <List>\n        {plan.map((d) => <ListRow title={`${d.day} · ${d.workout}`} subtitle={d.exercises.join(\", \")} href={`#/plan/${d.day}`} />)}\n      </List>\n    </div>\n  );\n}\n",
      "/src/screens/PlanDay.jsx": "import { useSettings } from \"amber\";\nimport { List, ListRow } from \"amber-ui\";\nimport ScreenHeader from \"../components/ScreenHeader.jsx\";\nimport { DEFAULTS, weight, useTraining } from \"../data.js\";\n\nexport default function PlanDay({ day: name }) {\n  const { plan, log } = useTraining();\n  const [{ unit }] = useSettings(DEFAULTS);\n  const day = plan.find((d) => d.day === name);\n  const best = (ex) => Math.max(0, ...log.items.filter((s) => s.exercise === ex).map((s) => s.weight));\n  return (\n    <div class=\"screen\">\n      <ScreenHeader title={day ? day.workout : name} subtitle={name} canGoBack />\n      <List>\n        {(day ? day.exercises : []).map((ex) => <ListRow title={ex} trailing={best(ex) ? `Best ${weight(best(ex), unit)}` : \"Not yet\"} />)}\n      </List>\n    </div>\n  );\n}\n",
      "/src/screens/Progress.jsx": "import { useState } from \"preact/hooks\";\nimport { useSettings } from \"amber\";\nimport { Stat, Tabs, Card } from \"amber-ui\";\nimport ScreenHeader from \"../components/ScreenHeader.jsx\";\nimport WeightChart from \"../components/WeightChart.jsx\";\nimport { DEFAULTS, today, weight, useTraining } from \"../data.js\";\n\nexport default function Progress() {\n  const { log } = useTraining();\n  const [{ unit, goal }] = useSettings(DEFAULTS);\n  const sets = log.items;\n  const names = [...new Set(sets.map((s) => s.exercise))].slice(0, 3);\n  const [pick, setPick] = useState(names[0]);\n\n  const points = sets.filter((s) => s.exercise === pick).map((s) => ({ date: s.date, kg: s.weight }));\n  const sessions = new Set(sets.map((s) => s.date)).size;\n  const weeks = Math.max(1, Math.round((Date.parse(today()) - Date.parse(sets[0]?.date ?? today())) / 6048e5));\n  return (\n    <div class=\"screen\">\n      <ScreenHeader title=\"Progress\" subtitle={`${sessions} sessions`} />\n      <div class=\"stats\">\n        <Stat value={sessions} label=\"sessions\" />\n        <Stat value={(sessions / weeks).toFixed(1)} label={`a week, goal ${goal}`} />\n        <Stat value={points.length ? weight(points[points.length - 1].kg, unit) : \"–\"} label={`${pick || \"\"} now`} />\n      </div>\n      <Tabs items={names} value={pick} onChange={setPick} label=\"Exercise\" />\n      <Card class=\"chart-card\"><WeightChart points={points} label={`${pick} over time`} /></Card>\n    </div>\n  );\n}\n",
      "/src/screens/Settings.jsx": "import { useSettings } from \"amber\";\nimport { List, ListRow, Tabs } from \"amber-ui\";\nimport ScreenHeader from \"../components/ScreenHeader.jsx\";\nimport { DEFAULTS } from \"../data.js\";\n\n// The app's own settings, kept in its data.\nexport default function Settings() {\n  const [settings, update] = useSettings(DEFAULTS);\n  return (\n    <div class=\"screen\">\n      <ScreenHeader title=\"Settings\" canGoBack />\n      <List>\n        <ListRow title=\"Units\" trailing={<Tabs items={[\"kg\", \"lb\"]} value={settings.unit} onChange={(unit) => update({ unit })} label=\"Units\" />} />\n        <ListRow title=\"Sessions a week\" subtitle=\"Your goal on Progress\"\n          trailing={<Tabs items={[2, 3, 4]} value={settings.goal} onChange={(goal) => update({ goal })} label=\"Sessions a week\" />} />\n      </List>\n    </div>\n  );\n}\n",
      "/src/screens/Today.jsx": "import { useState, useLayoutEffect } from \"preact/hooks\";\nimport { useSettings, setSummary } from \"amber\";\nimport { List, ListRow, Sheet, Input, Button, EmptyState } from \"amber-ui\";\nimport ScreenHeader from \"../components/ScreenHeader.jsx\";\nimport { DAYS, DEFAULTS, today, weight, lastSet, useTraining } from \"../data.js\";\n\nexport default function Today() {\n  const { plan, log } = useTraining();\n  const [{ unit }] = useSettings(DEFAULTS);\n  const [logging, setLogging] = useState(null), [kg, setKg] = useState(\"\");\n  const date = today(), dayName = DAYS[new Date().getDay()];\n  const day = plan.find((d) => d.day === dayName) || plan[0];\n\n  // The line under \"Training\" in the note list.\n  const sessions = new Set(log.items.map((s) => s.date)).size;\n  useLayoutEffect(() => { if (sessions) setSummary(`${sessions} sessions, last on ${log.items[log.items.length - 1].date}`); }, [sessions]);\n\n  if (!day) return <EmptyState title=\"No plan yet\" body=\"Add the days you train in Plan.\" />;\n  const done = (name) => log.items.some((s) => s.date === date && s.exercise === name);\n  const open = (name) => { setKg(String(lastSet(log, name)?.weight ?? \"\")); setLogging(name); };\n  const save = async () => {\n    const last = lastSet(log, logging);\n    await log.add({ date, exercise: logging, sets: last?.sets ?? 3, reps: last?.reps ?? 8, weight: +kg });\n    setLogging(null);\n  };\n\n  return (\n    <div class=\"screen\">\n      <ScreenHeader title=\"Today\" subtitle={`${day.workout} · ${day.day === dayName ? \"today\" : day.day}`} />\n      <List>\n        {day.exercises.map((name) => {\n          const last = lastSet(log, name);\n          return (\n            <ListRow title={name} subtitle={last ? `Last: ${last.sets} × ${last.reps} at ${weight(last.weight, unit)}` : \"First time\"}\n              trailing={done(name) ? <span class=\"logged\">Logged</span> : null}\n              onClick={done(name) ? undefined : () => open(name)} />\n          );\n        })}\n      </List>\n      <Sheet open={!!logging} onClose={() => setLogging(null)} title={logging || \"\"}\n        actions={<><Button variant=\"secondary\" onClick={() => setLogging(null)}>Cancel</Button><Button onClick={save} disabled={!kg}>Log Set</Button></>}>\n        <Input label=\"Weight (kg)\" inputmode=\"decimal\" value={kg} onInput={(e) => setKg(e.currentTarget.value)} hint=\"The same sets and reps as last time.\" />\n      </Sheet>\n    </div>\n  );\n}\n",
      "/src/styles.css": "/* Training's own styles. Plain CSS: it wins over amber-base and amber-ui, which sit in layers. */\n.screen { max-width: 720px; margin: 0 auto; padding: 16px var(--amber-gutter) 24px; }\n.screen-header { display: flex; align-items: center; gap: 10px; margin-bottom: 16px; }\n.screen-header__text { flex: 1; min-width: 0; }\n.screen-header h1 { font-size: 1.7rem; margin: 0; letter-spacing: -0.02em; }\n.screen-header p { margin: 2px 0 0; color: var(--amber-text-secondary); }\n.round { width: 36px; min-height: 36px; padding: 0; border-radius: 50%; }\n.logged { color: var(--amber-accent-text); font-weight: 600; }\n.stats { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; margin-bottom: 18px; }\n.chart-card { margin-top: 12px; padding: 8px; }\n.chart { width: 100%; height: auto; display: block; }\n.chart text { fill: var(--amber-text-secondary); font: 11px var(--amber-font); }\n.muted { color: var(--amber-text-secondary); }\n"
    }
  }
};
